import Foundation

struct UsageTimelineStrings {
    enum Key: Int, CaseIterable {
        case title, description, start, pause, resume, tracking, paused, appOnly, disabled,
             loading, empty, emptyHint, settings, active, away, allApps, details, copyTitle,
             copyPath, enable, titles, paths, idleThreshold, off, minutes, exclusions,
             exclude, remove, deleteDay, deleteAll, deleteTitle, deleteMessage, cancel,
             delete, storageError, retry, accessibility, permissionHelp, screenOff,
             locked, sleeping, switchedAway, idle, unrecorded, excluded, localHint,
             open, today, windowUnknown, loadMore, recentActivity
    }
    private let values: [String]
    init(_ language: AppLanguage) { values = Self.translation(language).components(separatedBy: "|") }
    subscript(_ key: Key) -> String { values[key.rawValue] }
    var isComplete: Bool { values.count == Key.allCases.count && values.allSatisfy { !$0.isEmpty } }
    func state(_ state: UsagePresence) -> String {
        switch state {
        case .active: return self[.active]
        case .idle: return self[.idle]
        case .screenOff: return self[.screenOff]
        case .locked: return self[.locked]
        case .sleeping: return self[.sleeping]
        case .switchedAway: return self[.switchedAway]
        case .paused: return self[.paused]
        case .excluded: return self[.excluded]
        case .unrecorded: return self[.unrecorded]
        }
    }

